-- STAGING ONLY. Active synthetic W03 claims; not a substitute for real HTTP tokens.
begin;
update public.organization_members set membership_status='active' where organization_id in(select id from public.organizations where slug like 'w03-synthetic-%-staging-v1-42182554295-1');
create temporary table w03_active_sql(actor text, target text, allowed boolean, seen bigint);
grant insert on w03_active_sql to authenticated;
do $$
declare u record; o record; n bigint; permitted boolean;
begin
 for u in select id,email from auth.users where raw_user_meta_data->>'w03_fixture'='w03-v1' and email like '%-42182554295-1@example.test' loop
  for o in select id,slug from organizations where slug like 'w03-synthetic-%-staging-v1-42182554295-1' loop
   select exists(select 1 from organization_members where organization_id=o.id and user_id=u.id and membership_status='active') into permitted;
   perform set_config('request.jwt.claim.sub',u.id::text,true);
   perform set_config('request.jwt.claims',json_build_object('sub',u.id,'role','authenticated')::text,true);
   execute 'set local role authenticated';
   select count(*) into n from public.projects where organization_id=o.id;
   insert into w03_active_sql values(u.email,o.slug,permitted,n);
   execute 'reset role';
   if not permitted and n<>0 then raise exception 'W03 foreign project SQL visibility';end if;
   if permitted and n<1 then raise exception 'W03 positive SQL project control missing';end if;
  end loop;
 end loop;
end $$;
do $$ begin
 if (select count(*) from w03_active_sql)<>57 or (select count(*) from w03_active_sql where not allowed)<>37 or (select count(*) from w03_active_sql where allowed)<>20 then raise exception 'W03 incomplete SQL matrix';end if;
end $$;
select allowed,count(*) as cases,min(seen) as min_rows,max(seen) as max_rows from w03_active_sql group by allowed;
rollback;

-- STAGING ONLY. Negative root-tenant, membership and access-grant mutations.
begin;
update public.organization_members set membership_status='active' where organization_id in(select id from public.organizations where slug like 'w03-synthetic-%-staging-v1-42182554295-1');
create temporary table w03_authority_cases(operation text,affected bigint);
grant insert on w03_authority_cases to authenticated;
do $$
declare u record;o record;member_id uuid;n bigint;denied boolean;
begin
 for u in select id from auth.users where raw_user_meta_data->>'w03_fixture'='w03-v1' and email like '%-42182554295-1@example.test' loop
  for o in select id from organizations where slug like 'w03-synthetic-%-staging-v1-42182554295-1' loop
   if exists(select 1 from organization_members where organization_id=o.id and user_id=u.id and membership_status='active') then continue;end if;
   select m.user_id into strict member_id from organization_members m join auth.users a on a.id=m.user_id
    where m.organization_id=o.id and a.email like 'w03-%-member-42182554295-1@example.test';
   perform set_config('request.jwt.claim.sub',u.id::text,true);
   perform set_config('request.jwt.claims',json_build_object('sub',u.id,'role','authenticated')::text,true);
   execute 'set local role authenticated';
   select count(*) into n from public.organizations where id=o.id;
   if n<>0 then raise exception 'Foreign organization READ';end if;
   insert into w03_authority_cases values('organization READ',n);
   begin
    update public.organizations set name='W03 forbidden mutation' where id=o.id;get diagnostics n=row_count;
   exception when insufficient_privilege then n:=0;end;
   if n<>0 then raise exception 'Foreign organization UPDATE';end if;
   insert into w03_authority_cases values('organization UPDATE',n);
   begin
    delete from public.organizations where id=o.id;get diagnostics n=row_count;
   exception when insufficient_privilege then n:=0;end;
   if n<>0 then raise exception 'Foreign organization DELETE';end if;
   insert into w03_authority_cases values('organization DELETE',n);
   denied:=false;
   begin
    insert into public.organization_members(organization_id,user_id,role,membership_status) values(o.id,u.id,'operator','active');
   exception when insufficient_privilege then denied:=true;end;
   if not denied then raise exception 'Foreign membership INSERT';end if;
   insert into w03_authority_cases values('membership INSERT',0);
   begin
    update public.organization_members set role='executive' where organization_id=o.id and user_id=member_id;get diagnostics n=row_count;
   exception when insufficient_privilege then n:=0;end;
   if n<>0 then raise exception 'Foreign membership UPDATE';end if;
   insert into w03_authority_cases values('membership UPDATE',n);
   begin
    delete from public.organization_members where organization_id=o.id and user_id=member_id;get diagnostics n=row_count;
   exception when insufficient_privilege then n:=0;end;
   if n<>0 then raise exception 'Foreign membership DELETE';end if;
   insert into w03_authority_cases values('membership DELETE',n);
   denied:=false;
   begin
    insert into public.crm_access_grants(organization_id,principal_type,principal_id,capability,resource_type,resource_id,granted_by)
    values(o.id,'user',member_id,'finance.read','company',o.id,u.id);
   exception when insufficient_privilege then denied:=true;
    when raise_exception then
     if sqlerrm<>'Only the active company owner can administer access' then raise;end if;
     denied:=true;
   end;
   if not denied then raise exception 'Foreign finance grant INSERT';end if;
   insert into w03_authority_cases values('finance grant INSERT',0);
   execute 'reset role';
  end loop;
 end loop;
 if (select count(*) from w03_authority_cases)<>259 then raise exception 'Incomplete W03 authority matrix';end if;
end $$;
select operation,count(*) as cases,sum(affected) as affected from w03_authority_cases group by operation order by operation;
rollback;

-- STAGING ONLY. SQL subject claims are a supplement to real token HTTP evidence.
-- Unpopulated relations are explicitly distinguished from positive-control coverage.
begin;
update public.organization_members set membership_status='active' where organization_id in(select id from public.organizations where slug like 'w03-synthetic-%-staging-v1-42182554295-1');
create temporary table w03_relations as
select c.relname,c.relkind from pg_class c join pg_namespace n on n.oid=c.relnamespace
where n.nspname='public' and c.relkind in ('r','p','v')
and exists(select 1 from pg_attribute a where a.attrelid=c.oid and a.attname='organization_id' and not a.attisdropped);
create temporary table w03_read_sweep(relation text,allowed boolean,seen bigint,denied boolean);
grant insert on w03_read_sweep to authenticated;
do $$
declare u record;o record;t record;n bigint;permitted boolean;denied boolean;
begin
 for u in select id from auth.users where raw_user_meta_data->>'w03_fixture'='w03-v1' and email like '%-42182554295-1@example.test' loop
  for o in select id from organizations where slug like 'w03-synthetic-%-staging-v1-42182554295-1' loop
   select exists(select 1 from organization_members where organization_id=o.id and user_id=u.id and membership_status='active') into permitted;
   perform set_config('request.jwt.claim.sub',u.id::text,true);
   perform set_config('request.jwt.claims',json_build_object('sub',u.id,'role','authenticated')::text,true);
   for t in select * from w03_relations loop
    execute 'set local role authenticated';
    n:=null;denied:=false;
    begin
     execute format('select count(*) from public.%I where organization_id=$1',t.relname) into n using o.id;
    exception when insufficient_privilege then denied:=true;
    end;
    insert into w03_read_sweep values(t.relname,permitted,n,denied);
    execute 'reset role';
    if not permitted and coalesce(n,0)<>0 then raise exception 'W03 foreign SQL visibility in %',t.relname;end if;
    if permitted and t.relname='projects' and (denied or coalesce(n,0)<>1) then raise exception 'W03 project positive control missing';end if;
   end loop;
  end loop;
 end loop;
 if (select count(*) from w03_relations)=0 or (select count(*) from w03_read_sweep)<>57*(select count(*) from w03_relations)
 or (select count(*) from w03_read_sweep where not allowed)<>37*(select count(*) from w03_relations)
 then raise exception 'W03 incomplete organization read sweep';end if;
end $$;
select json_build_object(
 'relations',(select count(*) from w03_relations),
 'cases',(select count(*) from w03_read_sweep),
 'foreignCases',(select count(*) from w03_read_sweep where not allowed),
 'foreignRows',(select coalesce(sum(seen),0) from w03_read_sweep where not allowed),
 'coverage',(select json_agg(x order by x.relation) from (
  select relation,count(*) filter(where not allowed) as foreign_cases,
   count(*) filter(where not allowed and denied) as foreign_permission_denied,
   max(seen) filter(where not allowed) as foreign_max_rows,
   count(*) filter(where allowed and seen>0) as positive_cases
  from w03_read_sweep group by relation
 )x)
) as evidence;
rollback;
